arguments.command:
cd /workspace/submission/src/offline && wc -l *.java && grep -n "System.err\|printStackTrace\|TODO\|FIXME" *.java; echo "--- imports check"; python3 - <<'EOF'
import re,pathlib
for p in sorted(pathlib.Path('.').glob('*.java')):
    s=p.read_text()
    body=s[s.index('public ') if 'public ' in s else 0:]
    used=set(re.findall(r'\b([A-Z][A-Za-z0-9_]*)\b', body))
    for m in re.findall(r'^import (?:static )?([\w.]+)\.(\w+);', s, re.M):
        if m[1] not in used and m[1]!='*':
            print(p.name, 'unused?', m[1])
EOF
